    private static func entry(_ title: String, _ composer: String, level: Int?, source: String,
                              midi: String, pdf: String?, info: String) -> CatalogEntry {
        let midiURL = URL(string: midi)!
        return CatalogEntry(id: midiURL.absoluteString, title: title, composer: composer, level: level, info: info,
                            previewURL: nil, pdfURL: pdf.flatMap(URL.init(string:)), midiURL: midiURL, zipURL: nil,
                            source: source)
    }
}
